{
  "name": "数字示波器",
  "name_en": "Digital Oscilloscope",
  "manufacturer": "",
  "description": "数字示波器是一种电子测试仪器，用于采集、显示和分析电压随时间变化的波形。它通常支持多通道输入，可用于电路调试、时域信号观测、脉冲与噪声分析，以及保存波形数据和仪器设置以便实验记录与重复测试。",
  "description_en": "A digital oscilloscope is an electronic test instrument used to acquire, display, and analyze voltage waveforms over time. It typically supports multiple input channels and is used for circuit debugging, time-domain signal observation, pulse and noise analysis, and saving waveform data and instrument setups for lab records and repeatable testing.",
  "actions": [
    {
      "action_name": "auto-chanAnaValidList",
      "description": "列出可用的模拟输入通道。",
      "description_en": "List the available analog input channels."
    },
    {
      "action_name": "auto-chanAllValidList",
      "description": "列出示波器支持的全部有效通道。",
      "description_en": "List all valid channels supported by the oscilloscope."
    },
    {
      "action_name": "auto-series",
      "description": "获取示波器的系列名称。",
      "description_en": "Get the oscilloscope series name."
    },
    {
      "action_name": "auto-getBestClass",
      "description": "识别已连接示波器的型号或系列。",
      "description_en": "Identify the model or series of the connected oscilloscope."
    },
    {
      "action_name": "auto-setupSave",
      "description": "将当前示波器设置导出并保存到文件。",
      "description_en": "Save the current oscilloscope setup to a file."
    },
    {
      "action_name": "auto-setupLoad",
      "description": "从文件恢复示波器设置。",
      "description_en": "Restore the oscilloscope setup from a file."
    },
    {
      "action_name": "auto-autoscale",
      "description": "自动调整显示与采集参数以稳定显示输入信号。",
      "description_en": "Automatically adjust display and acquisition settings to show the input signal clearly."
    },
    {
      "action_name": "auto-waveform",
      "description": "采集所选通道的波形数据并保存为CSV文件。",
      "description_en": "Acquire waveform data from a selected channel and save it to a CSV file."
    },
    {
      "action_name": "auto-waveformSaveCSV",
      "description": "将已采集的波形数据导出为CSV文件。",
      "description_en": "Export acquired waveform data to a CSV file."
    },
    {
      "action_name": "auto-waveformSaveNPZ",
      "description": "将已采集的波形数据导出为NPZ文件。",
      "description_en": "Export acquired waveform data to an NPZ file."
    },
    {
      "action_name": "auto-polish",
      "description": "将测量数值整理为合适的SI单位显示。",
      "description_en": "Format a measurement value using appropriate SI units."
    }
  ],
  "tag_hints": [
    "oscilloscope",
    "waveform acquisition",
    "time-domain measurement",
    "multi-channel signal analysis",
    "electronic test and debug",
    "autoscale",
    "waveform export"
  ]
}

